// The 16 National Career Clusters standard (US Dept. of Education / Advance
// CTE, 2002-2024) - a coarser, industry-standard grouping layered on top of
// DOMAINS_1112's own 27 domains via a crosswalk (verified in this session's
// "Career Cluster Map" reference doc). Most domains map straight across;
// a handful of individual careers are reassigned below their domain's
// default (see CAREER_ID_CLUSTER_OVERRIDE in the one-time patch script this
// field was generated from) because otherwise 3 of the 16 clusters
// (Manufacturing, Marketing, Transportation/Distribution/Logistics) would
// have zero careers under a strict domain-level mapping.
export type StandardCluster =
  | "Agriculture, Food & Natural Resources" | "Architecture & Construction"
  | "Arts, A/V Technology & Communications" | "Business Management & Administration"
  | "Education & Training" | "Finance" | "Government & Public Administration"
  | "Health Science" | "Hospitality & Tourism" | "Human Services"
  | "Information Technology" | "Law, Public Safety, Corrections & Security"
  | "Manufacturing" | "Marketing" | "STEM" | "Transportation, Distribution & Logistics";

export interface Career1112 {
  id: number;
  name: string;
  domain: string; // matches a DOMAINS_1112[].name
  cluster: StandardCluster;
  riasec: string; // 3-letter code, most-to-least dominant
  mi1: MICode;
  mi2: MICode;
  keyAptitude: AptCode;
  aptitudeLevel: AptLevel;
  requiredGroup: RequiredGroup;
  eligibleStreamsText: string; // display only - see file header
  values: string;
  shape: CareerPathShape;
  description: string;
  /** A representative undergraduate route - not the only one, but the most common. */
  typicalDegree: string;
  /** The entrance exam(s) that degree is typically reached through. */
  typicalEntranceExam: string;
  /** true for the 8 careers added beyond the kit's original 55 (see file header). */
  added?: boolean;
}

