/** Look up the roadmap for one career against one of this app's existing stream keys. */
export function roadmapFor(career: Career1112, appStreamKey: string): RoadmapEntry {
  const streamKey = STREAM_KEY_1112[appStreamKey] ?? "Vocational/Other";
  return ROADMAP_MATRIX[career.requiredGroup][streamKey];
}

export function careersByDomain(): Map<string, Career1112[]> {
  const map = new Map<string, Career1112[]>();
  for (const domain of DOMAINS_1112) map.set(domain.name, []);
  for (const career of CAREERS_1112) {
    const list = map.get(career.domain);
    if (list) list.push(career);
  }
  return map;
}
